BEGIN TRANSACTION;
CREATE TABLE "commission_rule" ("commission_rule_id" TEXT, "category" TEXT, "commission_rate_pct" TEXT, "reserve_rate_pct" TEXT, "effective_from" TEXT, "effective_to" TEXT, "is_active" TEXT);
CREATE TABLE "customer_review" ("review_id" TEXT, "order_line_id" TEXT, "seller_id" TEXT, "rating" TEXT, "review_date" TEXT, "review_text" TEXT);
CREATE TABLE "dispute" ("dispute_id" TEXT, "order_line_id" TEXT, "seller_id" TEXT, "dispute_type" TEXT, "dispute_status" TEXT, "dispute_amount" TEXT, "created_date" TEXT, "resolved_date" TEXT);
CREATE TABLE "event_history" ("event_id" TEXT, "entity_type" TEXT, "entity_id" TEXT, "event_type" TEXT, "event_date" TEXT, "from_state" TEXT, "to_state" TEXT);
CREATE TABLE "exception_cases" ("case_id" TEXT, "issue_type" TEXT, "ground_truth" TEXT, "expected_decision" TEXT, "affected_entity" TEXT, "affected_record_id" TEXT);
CREATE TABLE "fulfillment" ("fulfillment_id" TEXT, "order_line_id" TEXT, "seller_id" TEXT, "fulfillment_status" TEXT, "created_date" TEXT, "shipped_date" TEXT, "delivered_date" TEXT, "is_late" TEXT, "is_returned" TEXT);
CREATE TABLE "order" ("order_id" TEXT, "customer_id" TEXT, "order_date" TEXT, "order_status" TEXT, "order_total" TEXT, "currency" TEXT);
CREATE TABLE "order_line" ("order_line_id" TEXT, "order_id" TEXT, "listing_id" TEXT, "seller_id" TEXT, "quantity" TEXT, "unit_price" TEXT, "line_total" TEXT);
CREATE TABLE "payout" ("payout_id" TEXT, "seller_id" TEXT, "payout_date" TEXT, "payout_status" TEXT, "payout_total" TEXT, "currency" TEXT);
CREATE TABLE "payout_line" ("payout_line_id" TEXT, "payout_id" TEXT, "order_line_id" TEXT, "gross_amount" TEXT, "commission_amount" TEXT, "reserve_amount" TEXT, "refund_amount" TEXT, "net_amount" TEXT);
CREATE TABLE "product_listing" ("listing_id" TEXT, "seller_id" TEXT, "product_name" TEXT, "category" TEXT, "unit_price" TEXT, "listing_status" TEXT, "created_date" TEXT);
CREATE TABLE "seller" ("seller_id" TEXT, "seller_name" TEXT, "seller_status" TEXT, "country" TEXT, "created_date" TEXT, "service_level_target_pct" TEXT);
CREATE TABLE "seller_metrics" ("seller_id" TEXT, "delivered_fulfillment_count" TEXT, "late_fulfillment_count" TEXT, "on_time_rate_pct" TEXT, "average_review_rating" TEXT, "seller_status" TEXT, "meets_service_target" TEXT);
COMMIT;
